import {clone,uid,block} from './model.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const normalizeRitual=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
export function reviewedRituals(source){const map=new Map();for(const [title,meta,body] of Object.values(source.spells).flat()){if(!map.has(normalizeRitual(title)))map.set(normalizeRitual(title),{title,meta,body,summary:Object.values(source.summaries).flat().find(s=>normalizeRitual(s[0])===normalizeRitual(title))?.[1]||body});}return map;}
export function filterRituals(rituals,{query='',element='',circle='',source='',form=''}={}){const words=normalizeRitual(query).split(/\s+/).filter(Boolean);return rituals.filter(r=>(!element||r.elements.includes(element))&&(!circle||r.circle===Number(circle))&&(!source||r.sources.some(s=>s.id===source))&&(!form||r.forms.some(f=>f.name===form))&&words.every(word=>normalizeRitual([r.title,r.summary,...r.elements,...r.forms.map(f=>f.name)].join(' ')).includes(word)));}
export function createCatalogRitual(entry,{formName=entry.forms[0].name,element=entry.elements[0],mode='reference'}={},source){const form=entry.forms.find(f=>f.name===formName);if(!form)throw Error('Esta forma não está documentada para o ritual.');if(!entry.elements.includes(element))throw Error('Elemento incompatível com este ritual.');const reviewed=reviewedRituals(source).get(normalizeRitual(entry.title)),reviewedElement=reviewed?.meta.split('/')[0].trim();const canUseReviewed=reviewed&&form.name==='Básica'&&normalizeRitual(reviewedElement)===normalizeRitual(element);const original=entry.original,execution=(original.execution||'conforme fonte').replace(/^ação\s+/i,''),title=entry.title+(form.name==='Básica'?'':' — '+form.name);const citation=entry.sources.map(s=>`${s.title}, p. ${s.pdfPage} do PDF`).join('; ');const reference=`Referência Ordem: ${entry.circle}º círculo; ${form.costPE===null?'custo da forma não informado na ficha':form.costPE+' PE'}. Execução: ${execution}. Alcance: ${original.range||'conforme fonte'}. Duração: ${original.duration||'conforme fonte'}.${original.resistance?' Resistência: '+original.resistance+'.':''}`;let meta,body,summary,status;
 if(mode==='reviewed'){if(!canUseReviewed)throw Error('Não há uma conversão existente para esta combinação de forma e elemento.');({meta,body,summary}=clone(reviewed));status='existing';}
 else if(mode==='proposal'){const cost=[0,3,5,8,12][entry.circle]+(form.extraPE===null?0:Math.ceil(form.extraPE/2));meta=`${element} / ${cost} PD (PROPOSTA) / ${execution.toUpperCase()} / ${(original.range||'CONFORME FONTE').toUpperCase()}`;summary=entry.summary;body=entry.summary+(form.name!=='Básica'?`\nForma ${form.name} — referência de Ordem, não conversão numérica: ${form.referenceSummary}`:'')+`\n\nProposta de custo para Catastrophe: ${cost} PD${form.extraPE===null?'; o custo adicional desta forma não é informado pela fonte':''}. O efeito está resumido; valores, resistências, duração e limites precisam ser definidos antes de usá-lo em mesa. Não é uma conversão balanceada.\n${reference}`;status='proposal';}
 else if(mode==='reference'){meta=`${element} / ${entry.circle}º CÍRCULO / ${form.costPE===null?'PE NÃO INFORMADO':form.costPE+' PE'} / ${execution.toUpperCase()} / ${(original.range||'CONFORME FONTE').toUpperCase()}`;summary=entry.summary;body=entry.summary+(form.name!=='Básica'?`\n${form.name}: ${form.referenceSummary}`:'')+`\n\n${reference}\nResumo de referência de Ordem Paranormal; não convertido automaticamente para as regras de Catastrophe.`;status='reference';}
 else throw Error('Versão de ritual desconhecida.');
 if(form.requirements.length)body+='\nRequisitos na fonte: '+form.requirements.join('; ')+'.';if(entry.notes.length)body+='\nObservações da fonte: '+entry.notes.join(' ');
 return {id:uid(),title,meta,body,summary,catalogId:entry.id,ritualForm:form.name,ritualElement:element,originalCircle:entry.circle,adaptationStatus:status,sourceRefs:clone(entry.sources),referenceNote:citation};}
export function installRitualLibrary(E){let catalog=null,loading=null;const $=s=>document.querySelector(s);async function load(){if(catalog)return catalog;if(!loading)loading=fetch('./rituals.json').then(r=>{if(!r.ok)throw Error('Não foi possível carregar a biblioteca de rituais.');return r.json();}).then(data=>{if(data.version!==1||!Array.isArray(data.rituals)||!data.rituals.length||!Array.isArray(data.sources))throw Error('Biblioteca de rituais incompleta.');catalog=data;return data;}).catch(error=>{loading=null;throw error;});return loading;}
 async function open(){if(E.mode!=='edit')return;try{const data=await load(),reviewed=reviewedRituals(E.source);let selected=data.rituals[0],chosenMode=null;E.modal('Biblioteca de rituais',`<div class="ritual-library"><p class="subtle">${data.rituals.length} entradas · ${data.rituals.reduce((n,r)=>n+r.forms.length,0)} formas · ${data.sources.length} PDFs consultados. Resumos sem enredo. As conversões já usadas nos personagens permanecem intactas.</p><div class="ritual-filters"><label>Buscar<input id="ritualSearch" type="search" placeholder="Nome ou efeito, com ou sem acentos…"></label><label>Elemento<select id="ritualElementFilter"><option value="">Todos</option>${['CONHECIMENTO','ENERGIA','MORTE','SANGUE','MEDO'].map(e=>`<option>${e}</option>`).join('')}</select></label><label>Círculo<select id="ritualCircleFilter"><option value="">Todos</option>${[1,2,3,4].map(n=>`<option value="${n}">${n}º círculo</option>`).join('')}</select></label><label>Fonte<select id="ritualSourceFilter"><option value="">Todas</option>${data.sources.map(s=>`<option value="${s.id}" ${s.entries?'':'disabled'}>${esc(s.title)} (${s.entries})</option>`).join('')}</select></label><label>Forma<select id="ritualFormFilter"><option value="">Todas</option>${['Básica','Discente','Verdadeiro'].map(f=>`<option>${f}</option>`).join('')}</select></label></div><div class="ritual-catalog-grid"><div><small id="ritualResultCount" aria-live="polite"></small><div id="ritualResults" class="ritual-results" role="listbox" aria-label="Rituais encontrados"></div></div><section id="ritualPreview" class="ritual-preview" aria-label="Detalhes do ritual"></section></div><details class="ritual-source-audit"><summary>Fontes consultadas e cobertura</summary><p class="subtle">Incluídas descrições mecânicas e variantes nomeadas de fichas. Menções narrativas sem uma entrada mecânica e o enredo das missões não são reproduzidos. O número de página indica a página do arquivo PDF, contando a capa.</p>${data.sources.map(s=>`<p><strong>${esc(s.title)}</strong>: ${s.newEntries} entrada(s) nova(s), ${s.entries} entrada(s) referenciada(s).${s.entries?'':' Sem entradas mecânicas adicionais de rituais neste catálogo.'}</p>`).join('')}</details></div>`,`<button class="quiet" id="customCatalogRitual">Ritual personalizado</button><button class="quiet" data-action="close-modal">Cancelar</button><button class="primary" id="addCatalogRitual">Adicionar à ficha</button>`);
 function preview(){const holder=$('#ritualPreview'),add=$('#addCatalogRitual');if(!selected){holder.innerHTML='<p class="subtle">Nenhum ritual encontrado. Altere os filtros ou crie um ritual personalizado.</p>';add.disabled=true;return;}add.disabled=false;const existing=reviewed.get(normalizeRitual(selected.title));holder.innerHTML=`<h3>${esc(selected.title)}</h3><div class="ritual-tags"><span>${selected.elements.join(' · ')}</span><span>${selected.circle}º círculo original</span><span>${existing?'Conversão básica existente':'Referência disponível'}</span></div><p>${esc(selected.summary)}</p><div class="compact-grid"><label>Forma para adicionar<select id="ritualFormChoice">${selected.forms.map(f=>`<option>${f.name}</option>`).join('')}</select></label><label>Elemento da ficha<select id="ritualElementChoice">${selected.elements.map(e=>`<option>${e}</option>`).join('')}</select></label></div><label>Versão para a ficha<select id="ritualModeChoice"><option value="reference">Ordem — resumo de referência (PE)</option><option value="proposal">Catastrophe — proposta de custo (PD)</option><option value="reviewed">Catastrophe — conversão existente</option></select></label><div id="ritualFormDetails"></div><div id="ritualModeNotice" class="info-line"></div>${selected.notes.map(n=>`<p class="ritual-source-warning">${esc(n)}</p>`).join('')}<details><summary>Referências e variantes de fonte (${selected.sources.length})</summary>${selected.sources.map(s=>`<p class="ritual-citation">${esc(s.title)} · p. ${s.pdfPage} do PDF · ${esc(s.kind)}${s.note?'<br>'+esc(s.note):''}</p>`).join('')}</details>`;
 const desiredForm=$('#ritualFormFilter').value;if(desiredForm&&selected.forms.some(f=>f.name===desiredForm))$('#ritualFormChoice').value=desiredForm;const desiredElement=$('#ritualElementFilter').value;if(desiredElement&&selected.elements.includes(desiredElement))$('#ritualElementChoice').value=desiredElement;else if(existing){const preferred=existing.meta.split('/')[0].trim();if(selected.elements.includes(preferred))$('#ritualElementChoice').value=preferred;}
 function update(){const form=selected.forms.find(f=>f.name===$('#ritualFormChoice').value),element=$('#ritualElementChoice').value,canReview=existing&&form.name==='Básica'&&normalizeRitual(existing.meta.split('/')[0])===normalizeRitual(element),modeSelect=$('#ritualModeChoice');modeSelect.querySelector('[value="reviewed"]').disabled=!canReview;if(!chosenMode)modeSelect.value=canReview?'reviewed':'reference';else modeSelect.value=chosenMode==='reviewed'&&!canReview?'reference':chosenMode;const sample=createCatalogRitual(selected,{formName:form.name,element,mode:modeSelect.value},E.source);$('#ritualFormDetails').innerHTML=`<p><strong>${form.name}</strong> · ${form.costPE===null?'Custo original não especificado':form.costPE+' PE no Ordem'}${form.extraPE?` (base + ${form.extraPE} PE)`:''}</p>${form.name==='Básica'?'':`<p>${esc(form.referenceSummary)}</p>`}${form.requirements.length?`<p class="subtle">Requisitos originais: ${esc(form.requirements.join('; '))}</p>`:''}`;$('#ritualModeNotice').innerHTML=`<strong>${sample.adaptationStatus==='existing'?'Conversão já utilizada nos modelos':sample.adaptationStatus==='proposal'?'Proposta de custo — requer adaptação dos efeitos':'Referência de Ordem — sem conversão automática'}</strong><p>${esc(sample.meta)}</p><small>${sample.adaptationStatus==='proposal'?'Esta opção não converte nem balanceia automaticamente danos, bônus, resistências ou ações. Revise o texto no editor antes de usar.':sample.adaptationStatus==='reference'?'O resumo usa os círculos e PE de Ordem. As regras de Catastrophe não são alteradas.':'A descrição e os custos já usados nas fichas originais serão preservados.'}</small>`;}
 $('#ritualFormChoice').onchange=update;$('#ritualElementChoice').onchange=update;$('#ritualModeChoice').onchange=e=>{chosenMode=e.target.value;update();};update();}
 function results(){const list=filterRituals(data.rituals,{query:$('#ritualSearch').value,element:$('#ritualElementFilter').value,circle:$('#ritualCircleFilter').value,source:$('#ritualSourceFilter').value,form:$('#ritualFormFilter').value});if(!list.some(r=>r.id===selected?.id)){selected=list[0]||null;chosenMode=null;}$('#ritualResultCount').textContent=`${list.length} de ${data.rituals.length} entradas` ;$('#ritualResults').innerHTML=list.map(r=>`<button role="option" aria-selected="${r.id===selected?.id}" data-ritual-entry="${r.id}"><strong>${esc(r.title)}</strong><small>${r.elements.join(' · ')} · ${r.circle}º · ${r.forms.map(f=>f.name).join(', ')}</small></button>`).join('');$('#ritualResults').querySelectorAll('button').forEach(button=>button.onclick=()=>{selected=list.find(r=>r.id===button.dataset.ritualEntry);chosenMode=null;results();});preview();}
 for(const id of ['ritualSearch','ritualElementFilter','ritualCircleFilter','ritualSourceFilter','ritualFormFilter'])$('#'+id).addEventListener('input',results);$('#customCatalogRitual').onclick=()=>{const ritual={id:uid(),title:'Novo ritual',meta:'ELEMENTO / CUSTO / AÇÃO / ALCANCE',summary:'Descreva o efeito resumido.',body:'Descreva o efeito completo.'};insert(ritual);};$('#addCatalogRitual').onclick=()=>{if(selected)insert(createCatalogRitual(selected,{formName:$('#ritualFormChoice').value,element:$('#ritualElementChoice').value,mode:$('#ritualModeChoice').value},E.source));};results();
 }catch(err){E.toast(err.message);}}
 function insert(ritual){if(E.mode!=='edit')return;E.change(()=>{E.doc.rituals.push(ritual);if(!E.doc.blocks.some(b=>b.type==='rituals')){if(E.doc.blocks.length>=500)throw Error('Libere um elemento antes de criar o bloco de rituais.');E.doc.blocks.push(block('rituals','Rituais',1150,810,625,490,{font:22}));}},true,true);if(E.doc.rituals.some(r=>r.id===ritual.id))E.editRitual(ritual.id);}
 return {open,load};}
